import{_ as r,o as a,c as l,a2 as t}from"./chunks/framework.DfDAiEgj.js";const _=JSON.parse('{"title":"初入职场","description":"","frontmatter":{},"headers":[],"relativePath":"interview/enter.md","filePath":"interview/enter.md","lastUpdated":null}'),i={name:"interview/enter.md"};function o(n,e,p,h,s,c){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="初入职场" tabindex="-1">初入职场 <a class="header-anchor" href="#初入职场" aria-label="Permalink to &quot;初入职场&quot;">​</a></h1><p>完成日常工作之余，还主动了解公司架构、业务规范、部门内外合作流程。<a href="https://t.qidianla.com/1166342.html" target="_blank" rel="noreferrer">1</a></p><h2 id="一定不要做什么-2" tabindex="-1">一定不要做什么 <a href="http://www.jfrcw.com/zhichang/215586.html" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#一定不要做什么-2" aria-label="Permalink to &quot;一定不要做什么 [2]&quot;">​</a></h2><p>无论你的前任是怎么离开的，总会有些说不清道不明的原因，否则好的项目凭什么轮到你？所以在遇到项目真正的困难前，以下几件事情一定不要做，给自己增加难度了。</p><ol><li>当众诋毁前任产品经理，以及产品现状 这是一种最外行的行为，就像天天有人要教张小龙怎么做微信的吃瓜群众一般，上来就大批评产品的现状是多么的烂，前任产品是多么的无能。</li></ol><p>传到前任产品耳里不可怕，但如果传到之前为此付出过心血的研发、测试、运营、设计团队那里，你还准备让人跟你一起好好干嘛？</p><p>经常有人问，你这个绘本上的字体怎么不能调整字号，那谁谁家的就可以；你这个语音评测怎么这么慢，别人家的立即就能立即反馈结果。</p><p>最开始我还是比较在意的，直到有一天有人安慰到，说：“壳，我相信你当时做了最正确的判断。”是的，你不了解当时的情况，以及这样做的背景；没必要等到自己做的时候，同样的话送给了你自己，让众人嘲笑。</p><ol start="2"><li>给团队及领导画饼 有自信是好事，有行业经验也是好事，但换了个新环境、新团队、新公司就想把之前的经验照搬，给大家定目标，给领导画饼。</li></ol><p>见过两次有人接手我的项目：</p><p>一个是没做过这样类似的项目，但是是从大厂来的，想当然的迷之自信；笔者花半年时间才从2万做到10万顶峰日活，就敢给团队定个次年200万日活的目标，瞬间之前的研发、运营、设计都来给我吐槽，啥不也不懂，啥也不是。</p><p>另一个是之前做过类似项目，可能还挺成功，来了一个月却不和我进行深入的沟通和交流，成天沉迷商业模型的设计和PPT；结果去给高层做汇报，被当场diss到体无完肤；都说成功是不可复制的，你过去的成功未必能在新的平台和团队里做好，何况最后我仔细看了一眼，真是空中楼阁，浮夸。</p><ol start="3"><li>立即推进项目 这种可能是少数产品经理特有的一些特性。</li></ol><p>笔者之前带过整条业务线，总会希望各小组（研发、运营、设计等）保持住一种“状态”，有点像一辆车从静止到跑上高速，总会需要有一段加速的过程；那么我会希望在更重要的需求确定下来之前，先做一些简单不会错的事情，让大家热身起来，也是个磨合。</p><p>说实话，结果其实有好有坏，但实际推进过程中会遇到很多问题，特别是很难回答灵魂问题：“你的目标是什么，你做这个的收益是什么？”如果答不上来，难免会遇到一些尴尬，这种尴尬如果持续扩大，会产生更多的不信任。</p><ol start="4"><li>立即推倒项目 比立即推进项目更恶劣的情况就是直接把原有项目推倒重来，按照自己的想法来。</li></ol><p>怎么说呢，这个按我上面的思路再想想，你即不是皇帝，也不是CEO，初来乍到如果又没有什么成绩，why？不靠谱和不信任的标签将会长期被贴在身上。</p><p>我司的CTO来公司观察和学习小半年后，才做出了大刀阔斧的改革，他也没有借着之前的管理经验就硬上呀。</p><p>二、“接盘”的第一步：了解现状</p><p>因为<strong>你将接手的项目已经存在，甚至上线过很久，迭代过很多版本</strong>；虽然可能会有前任产品，或者上级领导做工作交接，但总会有很多不具体的地方，很多细节即使交接也未必清楚，或者年代久远没有记录。</p><p>先了解公司产品出于什么阶段了，现在做开发的成员人数。<a href="https://www.zhihu.com/question/38295860/answer/76188176" target="_blank" rel="noreferrer">3</a></p><h2 id="尽量做到" tabindex="-1">尽量做到 <a class="header-anchor" href="#尽量做到" aria-label="Permalink to &quot;尽量做到&quot;">​</a></h2><p>如果你刚成为AI产品经理尽量做到如下：<a href="https://www.zhihu.com/question/57815929/answer/1822975111" target="_blank" rel="noreferrer">6</a></p><ol><li>多问：问AI算法工程师调参的来龙去脉，</li><li>多做：自己标注和修改数据</li><li>多听：测试人员的体验优化建议</li><li>如果可以，每个岗位都轮一段时间。</li></ol><h2 id="劳动法" tabindex="-1">劳动法 <a class="header-anchor" href="#劳动法" aria-label="Permalink to &quot;劳动法&quot;">​</a></h2><p>中华人民共和国劳动法官网<a href="http://www.gov.cn/banshi/2005-05/25/content_905.htm" target="_blank" rel="noreferrer">10</a></p><p>《劳动法》<a href="https://www.bilibili.com/video/BV1pA411W7C5?from=search&amp;seid=12223012710879218878" target="_blank" rel="noreferrer">9</a></p><ul><li>第三十六条 国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。</li><li>第三十七条 对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。</li><li>第三十八条 用人单位应当保证劳动者每周至少休息一日。</li></ul><p>违法劳动法的问题尽快诉诸于法律</p><ol><li>认真学习法律知识。</li><li>当利益受到侵害时，直接下决心找劳动局/公安局。</li><li>劳动局/公安局说管不了，但法院能管的，打官司。</li><li>打官司不要吝惜请律师的钱。<a href="https://www.zhihu.com/question/426787072/answer/1589317013" target="_blank" rel="noreferrer">5</a></li></ol><p>《国务院关于工作时间的规定》第三条：职工每日工作时间8小时，每周工作时间40小时。</p><ol><li>员工合同到期，企业不愿意续约，需要赔偿吗？</li><li>法律保护的协商解除赔偿的最高赔偿金是n+1吗？</li><li>末位淘汰合法吗？<a href="https://zhuanlan.zhihu.com/p/143763092" target="_blank" rel="noreferrer">8</a></li><li>孕期女员工产假休假被拒绝，合理吗？</li><li>违反公司规章被开除没问题，对吗？<a href="https://www.zhihu.com/question/394383878/answer/1322178754" target="_blank" rel="noreferrer">7</a></li></ol>',32)])])}const w=r(i,[["render",o]]);export{_ as __pageData,w as default};
